p-flag-30-day-readmissions.solution:
import pandas as pd

def flag_readmissions(stays: pd.DataFrame) -> pd.DataFrame:
    s = stays.sort_values(["patient_id", "admit"]).reset_index(drop=True)
    s["prev_discharge"] = s.groupby("patient_id")["discharge"].shift()
    s["days_since_discharge"] = (s["admit"] - s["prev_discharge"]).dt.days
    s["readmit_30"] = s["days_since_discharge"].le(30)
    return s

def readmissions_per_patient(stays: pd.DataFrame) -> pd.Series:
    return flag_readmissions(stays).groupby("patient_id")["readmit_30"].sum()

