import pandas as pd

def monthly_totals(claims: pd.DataFrame) -> pd.DataFrame:
    return claims.assign(month=claims["service_date"].dt.to_period("M")).pivot_table(
        index="month", columns="payer", values="paid", aggfunc="sum", fill_value=0
    )

p-rolling-7-day-average-of-daily-admissi.solution:
import pandas as pd

def daily_admissions(admits: pd.DataFrame) -> pd.Series:
    day = admits["admit"].dt.floor("D")
    days = pd.date_range(day.min(), day.max(), freq="D")
    return day.value_counts().reindex(days, fill_value=0).sort_index()

def rolling_7_day_average(daily: pd.Series) -> pd.Series:
    return daily.rolling(7).mean()

