import pandas as pd

def one_hot(df: pd.DataFrame, columns: list[str] | None = None) -> pd.DataFrame:
    encoded = pd.get_dummies(df, columns=["payer", "plan_type"], dtype=int)
    return encoded if columns is None else encoded.reindex(columns=columns, fill_value=0)

