p-paid-amount-by-provider-specialty-with.solution:
import pandas as pd

def paid_by_specialty(claims: pd.DataFrame, providers: pd.DataFrame) -> pd.Series:
    joined = claims.merge(providers, on="npi", how="left", validate="many_to_one")
    joined["specialty"] = joined["specialty"].fillna("Unknown")
    return joined.groupby("specialty")["paid"].sum().sort_values(ascending=False)
